// Kernel dispatched with 1024 threads/block; each thread computes a per-lane path.
__global__ void div_kernel(const float* __restrict__ x, float* __restrict__ y) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    float v = x[tid];
    if (v > 0.0f) {
        y[tid] = expensive_path_a(v);   // takes T_A cycles
    } else {
        y[tid] = expensive_path_b(v);   // takes T_B cycles
    }
}
